//! Real/synthetic subject selection through actual PrepareQuery and same Host/Db.
use super::*;
use super::analysis_context_tests::{fixture,run,current};
use crate::policy_request::{AnalysisContext,WorkspaceAuxiliaryQuestion as Q};
#[path="../../../fixtures/unified_analysis_subject/source.rs"]mod initial;
fn setup(mode:&str)->(crate::runner_host::BuildHost,crate::request::BuildRequest,PathBuf){
 let(host,mut request,root)=fixture("/datum/temporary_setup\n");std::fs::remove_file(root.join("deepquarry.dme")).unwrap();std::fs::remove_file(root.join("code/probe.dm")).unwrap();
 for(relative,bytes)in initial::files(mode){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,bytes).unwrap();}
 let intent=request.policy_inputs.as_mut().unwrap();intent.analysis_context=Some(AnalysisContext::OriginalAnalyze0290);intent.workspace_auxiliary=vec![Q::SemReads];(host,request,root)
}
fn parse_all(snapshot:&SourceSnapshot){for ordinal in 0..snapshot.body_archive.as_ref().unwrap().len(){snapshot.body_archive.as_ref().unwrap().parse_checked(ordinal).unwrap();}}
#[test]fn actual_full_original_analyze_subject_matches_real_or_synthetic_code_and_warms_same_bodies(){
 for mode in initial::MODES{let(mut host,request,root)=setup(mode);let db=Arc::clone(host.query_db());run(&mut host,&request);
  let(first_tree,first_revision,header)=current(&host,|snapshot|{snapshot.require_analysis_context(Some(AnalysisContext::OriginalAnalyze0290)).unwrap();let subject=snapshot.analysis_subject.as_ref().unwrap();assert_eq!(subject.synthetic(),*mode!="real");let mapping=snapshot.source_mapping.as_ref().unwrap();subject.validate_mapping(mapping).unwrap();let(path,lease)=mapping.source_acquisitions().next().unwrap();let lease=lease.unwrap();if subject.synthetic(){assert!(crate::input_snapshot::recorded_source_original(lease).is_err());assert!(path.ends_with("__dmb_original_analysis_subject__/synth.dme"));}else{crate::input_snapshot::recorded_source_original(lease).unwrap();}
   assert!(snapshot.semantic_sources.as_ref().unwrap().check(mapping).is_ok());assert_eq!(snapshot.tree.lookup_type(dm_ir::SymbolId::of("/datum/real_manifest")).is_some(),*mode=="real");assert_eq!(snapshot.tree.lookup_type(dm_ir::SymbolId::of("/datum/ordered_correct")).is_some(),*mode!="real");assert!(snapshot.tree.lookup_type(dm_ir::SymbolId::of("/datum/ignored_manifest")).is_none());parse_all(snapshot);
   let mut types:Vec<_>=snapshot.tree.types().iter().map(|node|{let path=snapshot.tree.symbols().text(node.path).unwrap().to_owned();let id=snapshot.tree.lookup_type(node.path).unwrap();let parent=snapshot.tree.parent(id).map(|id|snapshot.tree.symbols().text(snapshot.tree.type_node(id).unwrap().path).unwrap().to_owned());(path,parent)}).collect();types.sort();println!("NATIVE_ANALYSIS_SUBJECT={}",serde_json::json!({"schema":"original-analysis-whole-subject-v1","case":mode,"types":types}));
   let guard=snapshot.workspace_native_read().unwrap();let workspace=snapshot.native_workspace.as_ref().unwrap();workspace.with_semantic_manifest(&guard,Q::SemReads,|bytes|{match *mode{"absent"=>assert!(bytes.is_none()),"invalid_utf8"=>assert!(std::str::from_utf8(bytes.unwrap()).is_err()),"noninclude"=>assert_eq!(bytes.unwrap(),b"/datum/ignored_manifest\n"),_=>assert!(bytes.unwrap().windows(8).any(|part|part==b"#include"))}Ok(())}).unwrap();(Arc::clone(&snapshot.tree),snapshot.source_revision,subject.header_for(path).map(|value|Arc::clone(value.prepared())))
  });let computed=db.db().stats(dm_query::Kind(4)).computed;run(&mut host,&request);current(&host,|snapshot|{assert!(Arc::ptr_eq(&first_tree,&snapshot.tree));assert_eq!(snapshot.source_revision,first_revision);parse_all(snapshot);if let Some(header)=&header{let subject=snapshot.analysis_subject.as_ref().unwrap();assert!(Arc::ptr_eq(header,subject.header_for(subject.project()).unwrap().prepared()));}});assert_eq!(db.db().stats(dm_query::Kind(4)).computed,computed);assert!(Arc::ptr_eq(&db,host.query_db()));assert!(host.serves_variant_context(&request.project,&request.defines,Some(AnalysisContext::OriginalAnalyze0290)));
  assert!(!root.join("__dmb_original_analysis_subject__").exists(),"generated root is not a fabricated physical input");
 }
}
#[test]fn actual_equal_real_original_purposes_share_frontend_variant_and_query_facts(){
 let(mut host,mut request,_)=setup("real");request.policy_inputs.as_mut().unwrap().analysis_context=Some(AnalysisContext::OriginalChecker0290);run(&mut host,&request);let state=host.query_state();let tree=current(&host,|snapshot|{parse_all(snapshot);assert!(snapshot.analysis_subject.is_none());assert!(snapshot.require_analysis_context(Some(AnalysisContext::OriginalAnalyze0290)).is_err());Arc::clone(&snapshot.tree)});let db=Arc::clone(host.query_db());let computed=db.db().stats(dm_query::Kind(4)).computed;request.policy_inputs.as_mut().unwrap().analysis_context=Some(AnalysisContext::OriginalAnalyze0290);run(&mut host,&request);assert!(Arc::ptr_eq(&state,&host.query_state()));assert!(Arc::ptr_eq(&db,host.query_db()));current(&host,|snapshot|{assert!(Arc::ptr_eq(&tree,&snapshot.tree));snapshot.require_analysis_context(Some(AnalysisContext::OriginalAnalyze0290)).unwrap();parse_all(snapshot);});assert_eq!(db.db().stats(dm_query::Kind(4)).computed,computed);
}
#[test]fn actual_synthetic_subject_discovery_change_reissues_and_wrong_context_or_incomplete_scope_refuses(){
 let(mut host,request,root)=setup("absent");run(&mut host,&request);let db=Arc::clone(host.query_db());let source=current(&host,|snapshot|snapshot.source_revision);std::fs::write(root.join("code/new.dm"),b"/datum/actual_new_subject_member\n").unwrap();run(&mut host,&request);current(&host,|snapshot|{assert_ne!(snapshot.source_revision,source);assert!(snapshot.tree.lookup_type(dm_ir::SymbolId::of("/datum/actual_new_subject_member")).is_some());assert!(snapshot.require_analysis_context(None).is_err());assert!(snapshot.workspace_generator_inputs(crate::GeneratorName::Reads).is_err());assert!(snapshot.resolved.is_none());assert!(snapshot.replay_proof.is_none());});assert!(Arc::ptr_eq(&db,host.query_db()));
 let mut wrong=request.clone();wrong.policy_inputs.as_mut().unwrap().workspace.as_mut().unwrap().recursive_roots=vec![root.join("maps")];let before=host.query_state();let error=crate::request_runner::run_build_with_host(wrong,&mut host).unwrap_err();assert!(error.to_string().contains("CODE_DM"));assert!(Arc::ptr_eq(&before,&host.query_state()));assert!(host.query_state().lock().unwrap().snapshot.is_some());
 let mut overrides=request;overrides.defines.insert("UNMATCHED".into(),"1".into());let error=crate::request_runner::run_build_with_host(overrides,&mut host).unwrap_err();assert_eq!(error.downcast_ref::<std::io::Error>().unwrap().kind(),std::io::ErrorKind::InvalidInput);
}

#[test]fn actual_synthetic_header_cannot_shadow_a_physical_namespace_or_gain_recorded_file_authority(){
 let(mut host,request,root)=setup("absent");std::fs::create_dir(root.join("__dmb_original_analysis_subject__")).unwrap();std::fs::write(root.join("__dmb_original_analysis_subject__/resource.dm"),b"/datum/unrelated_physical_resource\n").unwrap();let error=crate::request_runner::run_build_with_host(request,&mut host).unwrap_err();assert!(error.to_string().contains("namespace"));assert!(host.query_state().lock().unwrap().snapshot.is_none());assert_eq!(host.query_db().db().stats(dm_query::Kind(4)).computed,0);
}
